type Recipient =
  | { kind: 'channel'; name: string }
  | { kind: 'webhook'; url: URL };

async function fanOut(msg: Message, resolve: (m: Message) => Promise<Recipient[]>) {
  const recipients = await resolve(msg);
  const settled = await Promise.allSettled(
    recipients.map(r => deliver(r, structuredClone(msg))));
  return settled.filter((s): s is PromiseRejectedResult => s.status === 'rejected');
}
